import { Type } from 'typebox';
import { normalize } from '../normalize.mjs';

export default function (pi) {
  pi.registerTool({
    name: 'normalize_labels',
    description: 'Trim, discard empty labels, deduplicate, and sort values.',
    parameters: Type.Object({
      values: Type.Array(Type.String()),
    }),
    execute: async (_toolCallId, { values }) => ({
      content: [{ type: 'text', text: JSON.stringify(normalize(values)) }],
    }),
  });

  pi.on('agent_start', () => {
    globalThis.__d4HookRan = true;
  });
}

